1	import * as THREE from "three";
2	import { SceneObject } from "../../core/SceneObject.js";
3	import { Helpers } from "../../utils/Helpers.js";
4	import type {
5	  TransitionVeilTweenProps,
6	} from "../../types/object.types.js";
7	import type { TransitionVeilObjectOptions } from "../../types/object-visual.types.js";
8	import type {
9	  ShaderUniformRecord,
10	  TransitionVeilRuntimePort,
11	  TransitionVeilRuntimeState,
12	} from "../../types/object-runtime.types.js";
13	import transitionVeilVertexShader from "../../../shaders/who-reveal/vertex.glsl?raw";
14	import transitionVeilFragmentShader from "../../../shaders/who-reveal/fragment.glsl?raw";
15	
16	const TRANSITION_VEIL_RENDER_ORDER = 2200;
17	const TRANSITION_VEIL_DEFAULT_OPACITY = 0.96;
18	const TRANSITION_VEIL_DEFAULT_NOISE_STRENGTH = 1;
19	const TRANSITION_VEIL_DEFAULT_REVEAL_SOFTNESS = 0.24;
20	const TRANSITION_VEIL_DEFAULT_SIZE_X = 2.4;
21	const TRANSITION_VEIL_DEFAULT_SIZE_Y = 1.8;
22	const TRANSITION_VEIL_DEFAULT_COLOR_DARK = 0xc7d3de;
23	const TRANSITION_VEIL_DEFAULT_COLOR_LIGHT = 0xfbfdff;
24	const TRANSITION_VEIL_TIME_EPSILON = 0.0001;
25	const TRANSITION_VEIL_PROGRESS_EPSILON = 0.0001;
26	const TRANSITION_VEIL_DEFAULT_DISTANCE = 16;
27	const TRANSITION_VEIL_COVER_OVERSCAN = 1.35;
28	const TRANSITION_VEIL_CAMERA_FORWARD = new THREE.Vector3();
29	const TRANSITION_VEIL_CAMERA_RIGHT = new THREE.Vector3();
30	const TRANSITION_VEIL_CAMERA_UP = new THREE.Vector3();
31	const TRANSITION_VEIL_OFFSET = new THREE.Vector3();
32	
33	export class TransitionVeil
34	  extends SceneObject<TransitionVeilTweenProps>
35	  implements TransitionVeilRuntimePort
36	{
37	  private _options: Partial<TransitionVeilObjectOptions> = {};
38	  private _runtimeState: TransitionVeilRuntimeState = { active: false, progress: 0 };
39	  private _mesh: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial> | null =
40	    null;
41	  private _material: THREE.ShaderMaterial | null = null;
42	  private _noiseTexture: THREE.Texture | null = null;
43	  private _perlinTexture: THREE.Texture | null = null;
44	  private _elapsedTime = 0;
45	  private _lastActive = false;
46	  private _lastProgress = Number.NaN;
47	  private _lastResolutionWidth = 0;
48	  private _lastResolutionHeight = 0;
49	  private _lastTimeUniform = Number.NaN;
50	
51	  setOptions(props: Partial<TransitionVeilObjectOptions> | undefined): this {
52	    if (!props) return this;
53	    this._options = {
54	      ...this._options,
55	      ...props,
56	      position: { ...this._options.position, ...props.position },
57	      rotation: { ...this._options.rotation, ...props.rotation },
58	      scale: { ...this._options.scale, ...props.scale },
59	      plane: { ...this._options.plane, ...props.plane },
60	      shader: {
61	        ...this._options.shader,
62	        ...props.shader,
63	        textures: {
64	          ...this._options.shader?.textures,
65	          ...props.shader?.textures,
66	        },
67	        size: {
68	          ...this._options.shader?.size,
69	          ...props.shader?.size,
70	        },
71	      },
72	    };
73	    return this;
74	  }
75	
76	  setRuntimeState(state: Partial<TransitionVeilRuntimeState>): void {
77	    this._runtimeState = {
78	      ...this._runtimeState,
79	      ...state,
80	    };
81	    this._syncVisibility();
82	    if (!this._runtimeState.active) return;
83	    this._applyRuntimeUniforms();
84	  }
85	
86	  getRuntimeState(): TransitionVeilRuntimeState {
87	    return { ...this._runtimeState };
88	  }
89	
90	  override getAnimationTarget(): THREE.Object3D | null {
91	    return this.getTimelineRoot();
92	  }
93	
94	  override getBloomEnabled(): boolean {
95	    return false;
96	  }
97	
98	  override getTweenApplyMode(): "mergeAndSync" {
99	    return "mergeAndSync";
100	  }
101	
102	  protected override getOptions(): Record<string, unknown> {
103	    return this._options;
104	  }
105	
106	  protected override mergeOptionsFromTimeline(
107	    vars: Partial<TransitionVeilTweenProps>,
108	  ): void {
109	    if (vars.position) this._options.position = { ...this._options.position, ...vars.position };
110	    if (vars.rotation) this._options.rotation = { ...this._options.rotation, ...vars.rotation };
111	    if (vars.scale) this._options.scale = { ...this._options.scale, ...vars.scale };
112	    if (typeof vars.visible === "boolean") this._options.visible = vars.visible;
113	    if (typeof vars.progress === "number") this._runtimeState.progress = vars.progress;
114	    if (typeof vars.active === "boolean") this._runtimeState.active = vars.active;
115	  }
116	
117	  protected override applyVisibility(visible: boolean): void {
118	    const root = this.getTimelineRoot();
119	    if (!root) return;
120	    root.visible = visible && (this._runtimeState.active ?? false);
121	  }
122	
123	  protected override syncFromOptions(): void {
124	    this._applyStaticUniforms();
125	    this._syncVisibility();
126	  }
127	
128	  override async runObject(): Promise<void> {
129	    const scene = this._context?.scene;
130	    if (!scene) return;
131	
132	    const root = this.ensureTimelineRoot("transitionVeilRoot");
133	    if (!root) return;
134	    await this._loadTextures();
135	
136	    this._material = this._createMaterial();
137	    this._mesh = new THREE.Mesh(this._createGeometry(), this._material);
138	    this._mesh.frustumCulled = false;
139	    this._mesh.renderOrder = TRANSITION_VEIL_RENDER_ORDER;
140	    root.add(this._mesh);
141	
142	    this._followCamera();
143	    this._applyStaticUniforms();
144	    this._applyRuntimeUniforms();
145	    this._syncVisibility();
146	  }
147	
148	  override runUpdate(deltaTime: number): void {
149	    if (this._disposed) return;
150	    this._followCamera();
151	    if (!this._runtimeState.active) return;
152	    this._elapsedTime += Number.isFinite(deltaTime) ? Math.max(0, deltaTime) : 0;
153	    this._applyRuntimeUniforms();
154	  }
155	
156	  override dispose(): void {
157	    this._mesh?.geometry.dispose();
158	    this._material?.dispose();
159	    this._noiseTexture?.dispose();
160	    this._perlinTexture?.dispose();
161	    this._mesh = null;
162	    this._material = null;
163	    this._noiseTexture = null;
164	    this._perlinTexture = null;
165	    super.dispose();
166	  }
167	
168	  private async _loadTextures(): Promise<void> {
169	    const loadTexture = this._context?.loadTexture;
170	    const textures = this._options.shader?.textures;
171	    const perlinTextureUrl = textures?.perlinTextureUrl?.trim();
172	    const noiseTextureUrl = textures?.noiseTextureUrl?.trim();
173	    if (!loadTexture || !perlinTextureUrl || !noiseTextureUrl) return;
174	
175	    const [perlinTexture, noiseTexture] = await Promise.all([
176	      loadTexture(this.resolveAssetPath(perlinTextureUrl)),
177	      loadTexture(this.resolveAssetPath(noiseTextureUrl)),
178	    ]);
179	    this._prepareTexture(perlinTexture);
180	    this._prepareTexture(noiseTexture);
181	    this._perlinTexture = perlinTexture;
182	    this._noiseTexture = noiseTexture;
183	    this._context?.prepareTexture?.(perlinTexture);
184	    this._context?.prepareTexture?.(noiseTexture);
185	  }
186	
187	  private _prepareTexture(texture: THREE.Texture): void {
188	    texture.wrapS = THREE.RepeatWrapping;
189	    texture.wrapT = THREE.RepeatWrapping;
190	    texture.magFilter = THREE.LinearFilter;
191	    texture.minFilter = THREE.LinearMipmapLinearFilter;
192	    texture.needsUpdate = true;
193	  }
194	
195	  private _createGeometry(): THREE.PlaneGeometry {
196	    return new THREE.PlaneGeometry(1, 1, 1, 1);
197	  }
198	
199	  private _createMaterial(): THREE.ShaderMaterial {
200	    return new THREE.ShaderMaterial({
201	      uniforms: {
202	        uTime: { value: 0 },
203	        uProgress: { value: 0 },
204	        uOpacity: {
205	          value: this._finiteOr(
206	            this._options.shader?.opacity,
207	            TRANSITION_VEIL_DEFAULT_OPACITY,
208	          ),
209	        },
210	        uNoiseStrength: {
211	          value: this._finiteOr(
212	            this._options.shader?.noiseStrength,
213	            TRANSITION_VEIL_DEFAULT_NOISE_STRENGTH,
214	          ),
215	        },
216	        uRevealSoftness: {
217	          value: this._finiteOr(
218	            this._options.shader?.revealSoftness,
219	            TRANSITION_VEIL_DEFAULT_REVEAL_SOFTNESS,
220	          ),
221	        },
222	        uResolution: { value: new THREE.Vector2(1, 1) },
223	        uSize: {
224	          value: new THREE.Vector2(
225	            this._finiteOr(
226	              this._options.shader?.size?.x,
227	              TRANSITION_VEIL_DEFAULT_SIZE_X,
228	            ),
229	            this._finiteOr(
230	              this._options.shader?.size?.y,
231	              TRANSITION_VEIL_DEFAULT_SIZE_Y,
232	            ),
233	          ),
234	        },
235	        uDarkColor: {
236	          value: new THREE.Color(TRANSITION_VEIL_DEFAULT_COLOR_DARK),
237	        },
238	        uLightColor: {
239	          value: new THREE.Color(TRANSITION_VEIL_DEFAULT_COLOR_LIGHT),
240	        },
241	        tPerlin: { value: this._perlinTexture },
242	        tNoise: { value: this._noiseTexture },
243	      },
244	      vertexShader: transitionVeilVertexShader,
245	      fragmentShader: transitionVeilFragmentShader,
246	      transparent: true,
247	      depthWrite: false,
248	      depthTest: false,
249	      side: THREE.DoubleSide,
250	    });
251	  }
252	
253	  private _applyStaticUniforms(): void {
254	    const uniforms = this._material?.uniforms as ShaderUniformRecord | undefined;
255	    if (!uniforms) return;
256	    this._followCamera();
257	    this._setUniformNumber(
258	      uniforms,
259	      "uOpacity",
260	      this._finiteOr(
261	        this._options.shader?.opacity,
262	        TRANSITION_VEIL_DEFAULT_OPACITY,
263	      ),
264	    );
265	    this._setUniformNumber(
266	      uniforms,
267	      "uNoiseStrength",
268	      this._finiteOr(
269	        this._options.shader?.noiseStrength,
270	        TRANSITION_VEIL_DEFAULT_NOISE_STRENGTH,
271	      ),
272	    );
273	    this._setUniformNumber(
274	      uniforms,
275	      "uRevealSoftness",
276	      this._finiteOr(
277	        this._options.shader?.revealSoftness,
278	        TRANSITION_VEIL_DEFAULT_REVEAL_SOFTNESS,
279	      ),
280	    );
281	    const size = uniforms.uSize?.value;
282	    if (!(size instanceof THREE.Vector2)) return;
283	    size.set(
284	      this._finiteOr(
285	        this._options.shader?.size?.x,
286	        TRANSITION_VEIL_DEFAULT_SIZE_X,
287	      ),
288	      this._finiteOr(
289	        this._options.shader?.size?.y,
290	        TRANSITION_VEIL_DEFAULT_SIZE_Y,
291	      ),
292	    );
293	  }
294	
295	  private _applyRuntimeUniforms(): void {
296	    const uniforms = this._material?.uniforms as ShaderUniformRecord | undefined;
297	    if (!uniforms) return;
298	    const isActive = this._runtimeState.active ?? false;
299	    const progress = Helpers.clamp01(
300	      this._runtimeState.progress ?? this._options.progress ?? 0,
301	    );
302	    if (
303	      isActive ||
304	      this._lastActive !== isActive ||
305	      Math.abs(progress - this._lastProgress) > TRANSITION_VEIL_PROGRESS_EPSILON
306	    ) {
307	      this._setUniformNumber(uniforms, "uProgress", progress);
308	      this._lastProgress = progress;
309	    }
310	    if (
311	      isActive &&
312	      Math.abs(this._elapsedTime - this._lastTimeUniform) > TRANSITION_VEIL_TIME_EPSILON
313	    ) {
314	      this._setUniformNumber(uniforms, "uTime", this._elapsedTime);
315	      this._lastTimeUniform = this._elapsedTime;
316	    }
317	    const resolution = uniforms.uResolution?.value;
318	    const renderer = this._context?.renderer;
319	    const width = renderer?.domElement?.width;
320	    const height = renderer?.domElement?.height;
321	    if (!(resolution instanceof THREE.Vector2)) return;
322	    if (!Number.isFinite(width) || !Number.isFinite(height)) return;
323	    const nextWidth = width as number;
324	    const nextHeight = height as number;
325	    if (
326	      nextWidth !== this._lastResolutionWidth ||
327	      nextHeight !== this._lastResolutionHeight
328	    ) {
329	      resolution.set(nextWidth, nextHeight);
330	      this._lastResolutionWidth = nextWidth;
331	      this._lastResolutionHeight = nextHeight;
332	    }
333	    this._lastActive = isActive;
334	  }
335	
336	  private _syncVisibility(): void {
337	    const root = this.getTimelineRoot();
338	    if (!root) return;
339	    root.visible = this._options.visible !== false && (this._runtimeState.active ?? false);
340	  }
341	
342	  private _followCamera(): void {
343	    const root = this.getTimelineRoot();
344	    const camera = this._context?.camera;
345	    if (!root || !camera) return;
346	
347	    const distance = this._resolveDistance();
348	    camera.getWorldDirection(TRANSITION_VEIL_CAMERA_FORWARD);
349	    root.quaternion.copy(camera.quaternion);
350	    root.position.copy(camera.position).addScaledVector(
351	      TRANSITION_VEIL_CAMERA_FORWARD,
352	      distance,
353	    );
354	
355	    TRANSITION_VEIL_CAMERA_RIGHT.set(1, 0, 0).applyQuaternion(camera.quaternion);
356	    TRANSITION_VEIL_CAMERA_UP.set(0, 1, 0).applyQuaternion(camera.quaternion);
357	    TRANSITION_VEIL_OFFSET.set(
358	      this._finiteOr(this._options.position?.x, 0),
359	      this._finiteOr(this._options.position?.y, 0),
360	      this._finiteOr(this._options.position?.z, 0),
361	    );
362	    root.position
363	      .addScaledVector(TRANSITION_VEIL_CAMERA_RIGHT, TRANSITION_VEIL_OFFSET.x)
364	      .addScaledVector(TRANSITION_VEIL_CAMERA_UP, TRANSITION_VEIL_OFFSET.y)
365	      .addScaledVector(TRANSITION_VEIL_CAMERA_FORWARD, TRANSITION_VEIL_OFFSET.z);
366	
367	    const coverSize = this._resolveCoverSize(camera, distance);
368	    const planeWidth = this._finiteOr(this._options.plane?.width, coverSize.width);
369	    const planeHeight = this._finiteOr(this._options.plane?.height, coverSize.height);
370	    root.scale.set(
371	      Math.max(planeWidth, coverSize.width),
372	      Math.max(planeHeight, coverSize.height),
373	      1,
374	    );
375	  }
376	
377	  private _resolveDistance(): number {
378	    return this._finiteOr(
379	      this._options.plane?.distance,
380	      TRANSITION_VEIL_DEFAULT_DISTANCE,
381	    );
382	  }
383	
384	  private _resolveCoverSize(
385	    camera: THREE.Camera,
386	    distance: number,
387	  ): { width: number; height: number } {
388	    if (camera instanceof THREE.PerspectiveCamera) {
389	      const verticalFov = THREE.MathUtils.degToRad(camera.fov);
390	      const height =
391	        2 * Math.tan(verticalFov * 0.5) * distance * TRANSITION_VEIL_COVER_OVERSCAN;
392	      return {
393	        width: height * camera.aspect,
394	        height,
395	      };
396	    }
397	    if (camera instanceof THREE.OrthographicCamera) {
398	      const width =
399	        ((camera.right - camera.left) / Math.max(camera.zoom, 0.0001)) *
400	        TRANSITION_VEIL_COVER_OVERSCAN;
401	      const height =
402	        ((camera.top - camera.bottom) / Math.max(camera.zoom, 0.0001)) *
403	        TRANSITION_VEIL_COVER_OVERSCAN;
404	      return { width, height };
405	    }
406	    return {
407	      width: this._finiteOr(this._options.plane?.width, 1) * TRANSITION_VEIL_COVER_OVERSCAN,
408	      height: this._finiteOr(this._options.plane?.height, 1) * TRANSITION_VEIL_COVER_OVERSCAN,
409	    };
410	  }
411	
412	  private _setUniformNumber(
413	    uniforms: ShaderUniformRecord,
414	    key: string,
415	    value: number,
416	  ): void {
417	    const target = uniforms[key];
418	    if (!target) return;
419	    target.value = value;
420	  }
421	
422	  private _finiteOr(value: number | undefined, fallback: number): number {
423	    return Number.isFinite(value) ? (value as number) : fallback;
424	  }
425	}
